/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: withPhrase, keys
 *   Constants: mbid, added, schemaOrder
 * Tests
 *   - a new entry is primary, joins the end of the primary group and keeps every other entry, and the list stops at 20 entries
 *   - removing an entry keeps every other key and phrase, and the entry left last loses its phrase
 *   - an entry moves only within its role group while each join phrase stays in its position, and a blocked move returns the same list
 *   - a role change moves the entry to the start of the featured group or the end of the primary group, so every primary precedes every featured entry
 *   - a rename keeps key, role and phrase, and keeps the MusicBrainz ID only while the name matches the saved entry
 *   - an empty join phrase is none and a typed phrase is kept verbatim, without changing a role
 *   - a blank label field is no label, and a renamed label keeps its MusicBrainz ID only while the name matches
 *   - entry names are required, refuse control and invisible formatting characters, stay within 200 characters after NFC, and differ case-insensitively
 *   - join phrases are checked as the server checks them
 *   - a label refuses control and invisible formatting characters and more than 200 characters after NFC
 * @end-catalog */

import type { ImportArtistEntry } from './adminApi';
import { ARTIST_ENTRY_LIMIT, addArtistEntry, artistEntryIssues, canMoveArtistEntry, foldEntryName, labelFromInput, labelIssue, moveArtistEntry, removeArtistEntry, renameArtistEntry, setArtistEntryPhrase, setArtistEntryRole, validJoinPhrase } from './importArtistEntries';
import { entriesByline } from './importDraftPatch';
import { artistEntry, entryKey, labelEntry } from './adminFixtures.testSupport';

const mbid = '30000000-0000-4000-9000-000000000003', added = entryKey(99);
const withPhrase = (entry: ImportArtistEntry, joinPhrase: string | null) => ({ ...entry, joinPhrase });
const keys = (entries: readonly ImportArtistEntry[]) => entries.map(entry => entry.key);
const schemaOrder = ['key', 'name', 'role', 'joinPhrase', 'musicBrainzId'];

test('a new entry is primary, joins the end of the primary group and keeps every other entry, and the list stops at 20 entries', () => {
  const entries = [withPhrase(artistEntry('Lorem'), ' & '), artistEntry('Ipsum', entryKey(2)), withPhrase(artistEntry('Dolor', entryKey(3), 'featured'), ' x ')];
  const next = addArtistEntry(entries, added), blank = { key: added, name: '', role: 'primary', joinPhrase: null, musicBrainzId: null };
  // The featured entry stays last, so a phrase stored there is cleared.
  expect(next).toEqual([entries[0], entries[1], blank, withPhrase(entries[2], null)]);
  expect(Object.keys(next[2])).toEqual(schemaOrder);
  expect(addArtistEntry([], added)).toEqual([blank]);
  expect(addArtistEntry([artistEntry('Lorem')], added)).toEqual([artistEntry('Lorem'), blank]);
  const full = Array.from({ length: ARTIST_ENTRY_LIMIT }, (_, index) => artistEntry(`Name ${index}`, entryKey(index + 1)));
  expect(addArtistEntry(full, added)).toBe(full);
  expect(addArtistEntry(full.slice(1), added)).toHaveLength(ARTIST_ENTRY_LIMIT);
});

test('removing an entry keeps every other key and phrase, and the entry left last loses its phrase', () => {
  const entries = [withPhrase(artistEntry('Lorem'), ' & '), withPhrase(artistEntry('Ipsum', entryKey(2)), ' feat. '), artistEntry('Dolor', entryKey(3), 'featured')];
  expect(removeArtistEntry(entries, entryKey(1))).toEqual([entries[1], entries[2]]);
  expect(removeArtistEntry(entries, entryKey(2))).toEqual([entries[0], entries[2]]);
  expect(removeArtistEntry(entries, entryKey(3))).toEqual([entries[0], withPhrase(entries[1], null)]);
  expect(removeArtistEntry([entries[0]], entryKey(1))).toEqual([]);
  expect(removeArtistEntry(entries, entryKey(9))).toBe(entries);
});

test('an entry moves only within its role group while each join phrase stays in its position, and a blocked move returns the same list', () => {
  const entries = [withPhrase(artistEntry('Lorem'), ' & '), withPhrase(artistEntry('Ipsum', entryKey(2)), ' feat. '), withPhrase(artistEntry('Dolor', entryKey(3), 'featured'), ' x '), artistEntry('Sit', entryKey(4), 'featured')];
  const swapped = [withPhrase(entries[1], ' & '), withPhrase(entries[0], ' feat. '), entries[2], entries[3]];
  expect(moveArtistEntry(entries, entryKey(2), -1)).toEqual(swapped); expect(moveArtistEntry(entries, entryKey(1), 1)).toEqual(swapped);
  expect(Object.keys(swapped[0])).toEqual(schemaOrder); expect(entriesByline(moveArtistEntry(entries, entryKey(2), -1))).toBe('Ipsum & Lorem feat. Dolor x Sit');
  // "A & B feat. C" with A and B swapped reads "B & A feat. C".
  const byline = [withPhrase(artistEntry('A'), ' & '), withPhrase(artistEntry('B', entryKey(2)), ' feat. '), artistEntry('C', entryKey(3), 'featured')];
  expect(entriesByline(moveArtistEntry(byline, entryKey(1), 1))).toBe('B & A feat. C');
  expect(moveArtistEntry(entries, entryKey(3), 1)).toEqual([entries[0], entries[1], withPhrase(entries[3], ' x '), withPhrase(entries[2], null)]);
  // A phrase stored on the last entry is still cleared, as the last name connects to nothing.
  const stored = [withPhrase(artistEntry('Lorem'), ' & '), withPhrase(artistEntry('Ipsum', entryKey(2)), ' + ')];
  expect(moveArtistEntry(stored, entryKey(1), 1)).toEqual([withPhrase(stored[1], ' & '), withPhrase(stored[0], null)]);
  expect([[0, -1], [1, 1], [2, -1], [3, 1], [0, 1], [3, -1]].map(([index, direction]) => canMoveArtistEntry(entries, index, direction as -1 | 1))).toEqual([false, false, false, false, true, true]);
  // The top, the bottom, both sides of the primary/featured boundary and an unknown key.
  for (const [key, direction] of [[entryKey(1), -1], [entryKey(4), 1], [entryKey(2), 1], [entryKey(3), -1], [entryKey(9), 1]] as const) expect(moveArtistEntry(entries, key, direction)).toBe(entries);
});

test('a role change moves the entry to the start of the featured group or the end of the primary group, so every primary precedes every featured entry', () => {
  const entries = [artistEntry('Lorem'), withPhrase(artistEntry('Ipsum', entryKey(2)), ' feat. '), withPhrase(artistEntry('Dolor', entryKey(3), 'featured'), ' & '), artistEntry('Sit', entryKey(4), 'featured')];
  const featured = setArtistEntryRole(entries, entryKey(1), 'featured');
  expect(keys(featured)).toEqual([entryKey(2), entryKey(1), entryKey(3), entryKey(4)]); expect(featured[1]).toEqual({ ...entries[0], role: 'featured' });
  expect(keys(setArtistEntryRole(entries, entryKey(4), 'primary'))).toEqual([entryKey(1), entryKey(2), entryKey(4), entryKey(3)]);
  expect(setArtistEntryRole(entries, entryKey(3), 'primary')[2]).toEqual({ ...entries[2], role: 'primary' });
  // An entry a role change leaves last loses its phrase; an unchanged role or unknown key returns the same list.
  expect(setArtistEntryRole([withPhrase(artistEntry('Lorem'), ' & '), artistEntry('Ipsum', entryKey(2))], entryKey(1), 'featured')).toEqual([artistEntry('Ipsum', entryKey(2)), artistEntry('Lorem', entryKey(1), 'featured')]);
  expect(setArtistEntryRole(entries, entryKey(2), 'primary')).toBe(entries); expect(setArtistEntryRole(entries, entryKey(9), 'featured')).toBe(entries);
  for (const pattern of ['ppp', 'ppf', 'pff', 'fff']) {
    const start = [...pattern].map((role, index) => artistEntry(`Name ${index}`, entryKey(index + 1), role === 'p' ? 'primary' : 'featured'));
    for (const entry of start) for (const role of ['primary', 'featured'] as const) {
      const result = setArtistEntryRole(start, entry.key, role), firstFeatured = result.findIndex(item => item.role === 'featured');
      expect(firstFeatured < 0 || result.slice(firstFeatured).every(item => item.role === 'featured'), `${pattern} ${entry.name} ${role}`).toBe(true);
      expect(keys(result).sort()).toEqual(keys(start)); expect(result.find(item => item.key === entry.key)?.role).toBe(role);
    }
  }
});

test('a rename keeps key, role and phrase, and keeps the MusicBrainz ID only while the name matches the saved entry', () => {
  const saved = [{ ...artistEntry('Caf\u00E9', entryKey(1), 'featured'), joinPhrase: ' & ', musicBrainzId: mbid }, artistEntry('Ipsum', entryKey(2), 'featured')];
  const renamed = renameArtistEntry(saved, entryKey(1), 'Lorem', saved);
  expect(renamed[0]).toEqual({ ...saved[0], name: 'Lorem', musicBrainzId: null }); expect(renamed[1]).toBe(saved[1]); expect(Object.keys(renamed[0])).toEqual(schemaOrder);
  // Case, composition and surrounding spaces do not rename the entry, so its ID comes back.
  for (const name of ['CAF\u00C9', 'cafe\u0301', '  Caf\u00E9 ']) expect(renameArtistEntry(renamed, entryKey(1), name, saved)[0]).toEqual({ ...saved[0], name });
  expect(renameArtistEntry(renamed, entryKey(1), 'Caf\u00E9', saved)).toEqual(saved);
  expect(renameArtistEntry(saved, entryKey(1), '', saved)[0]).toEqual({ ...saved[0], name: '', musicBrainzId: null });
  // A new entry has no saved ID to keep, and an unchanged name or unknown key returns the same list.
  expect(renameArtistEntry([artistEntry('', added)], added, 'Caf\u00E9', saved)[0].musicBrainzId).toBeNull();
  expect(renameArtistEntry(saved, entryKey(1), 'Caf\u00E9', saved)).toBe(saved); expect(renameArtistEntry(saved, added, 'Lorem', saved)).toBe(saved);
  expect(foldEntryName(' CAFE\u0301 ')).toBe('caf\u00E9');
});

test('an empty join phrase is none and a typed phrase is kept verbatim, without changing a role', () => {
  const entries = [withPhrase(artistEntry('Lorem', entryKey(1), 'featured'), ' & '), artistEntry('Ipsum', entryKey(2), 'featured')];
  expect(setArtistEntryPhrase(entries, entryKey(1), '')).toEqual([withPhrase(entries[0], null), entries[1]]);
  expect(setArtistEntryPhrase(entries, entryKey(1), ' feat. ')[0]).toEqual(withPhrase(entries[0], ' feat. '));
  expect(setArtistEntryPhrase(entries, entryKey(1), ' & ')).toBe(entries); expect(setArtistEntryPhrase(entries, added, ' & ')).toBe(entries);
});

test('a blank label field is no label, and a renamed label keeps its MusicBrainz ID only while the name matches', () => {
  const saved = { name: 'Lorem Records', musicBrainzId: mbid };
  expect(labelFromInput('', saved)).toBeNull(); expect(labelFromInput(' \t ', saved)).toBeNull();
  expect(labelFromInput('LOREM records ', saved)).toEqual({ name: 'LOREM records ', musicBrainzId: mbid });
  expect(labelFromInput('Ipsum Records', saved)).toEqual({ name: 'Ipsum Records', musicBrainzId: null });
  expect(labelFromInput('Lorem Records', null)).toEqual(labelEntry('Lorem Records')); expect(Object.keys(labelFromInput('Lorem', saved)!)).toEqual(['name', 'musicBrainzId']);
});

test('entry names are required, refuse control and invisible formatting characters, stay within 200 characters after NFC, and differ case-insensitively', () => {
  const entries = [artistEntry('Lorem', entryKey(1)), artistEntry('   ', entryKey(2)), artistEntry('Bad\u200BName', entryKey(3)), artistEntry('Bell\u0007', entryKey(4)), artistEntry('LOREM', entryKey(5)),
    artistEntry('Caf\u00E9', entryKey(6)), artistEntry(' cafe\u0301', entryKey(7), 'featured'), artistEntry('Lone\uD800', entryKey(8), 'featured')];
  // Every entry sharing a folded name is marked, so renaming the first to match the second marks both.
  expect(Object.fromEntries(artistEntryIssues(entries))).toEqual({ [entryKey(1)]: { name: 'duplicate' }, [entryKey(2)]: { name: 'required' }, [entryKey(3)]: { name: 'invalid' }, [entryKey(4)]: { name: 'invalid' }, [entryKey(5)]: { name: 'duplicate' }, [entryKey(6)]: { name: 'duplicate' }, [entryKey(7)]: { name: 'duplicate' }, [entryKey(8)]: { name: 'invalid' } });
  // As the server trims after NFC, an edge U+FEFF is dropped and accepted, while one inside the name is refused.
  expect(artistEntryIssues([artistEntry('\uFEFFLorem'), artistEntry('Ipsum\uFEFF', entryKey(2))]).size).toBe(0);
  expect(Object.fromEntries(artistEntryIssues([artistEntry('Lo\uFEFFrem')]))).toEqual({ [entryKey(1)]: { name: 'invalid' } });
  expect(Object.fromEntries(artistEntryIssues([artistEntry('\uFEFFLorem'), artistEntry('lorem', entryKey(2))]))).toEqual({ [entryKey(1)]: { name: 'duplicate' }, [entryKey(2)]: { name: 'duplicate' } });
  // U+0958 normalizes to two units, so 101 of them are 202 characters to the server.
  expect(Object.fromEntries(artistEntryIssues([artistEntry('\u0958'.repeat(101)), artistEntry('x'.repeat(201), entryKey(2))]))).toEqual({ [entryKey(1)]: { name: 'too_long' }, [entryKey(2)]: { name: 'too_long' } });
  expect(artistEntryIssues([artistEntry('\u0958'.repeat(100)), artistEntry(` ${'x'.repeat(198)} `, entryKey(2))]).size).toBe(0);
  expect(artistEntryIssues([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2))]).size).toBe(0);
  expect(Object.fromEntries(artistEntryIssues([withPhrase(artistEntry(''), 'a\u200Bb'), withPhrase(artistEntry('Ipsum', entryKey(2)), ' & ')]))).toEqual({ [entryKey(1)]: { name: 'required', phrase: 'invalid' } });
});

test('join phrases are checked as the server checks them', () => {
  // Copied from test/catalog/catalogCredit.test.ts, without the non-string values the editor cannot produce.
  const accepted = ['\u3001', ' & ', ' feat. ', '&', '\u00A0&\u00A0', 'x'.repeat(16), '\u{1F3BB}'.repeat(8), '\u2764\uFE0F', ' \u{1F1EF}\u{1F1F5} ', ' ve\u0301s ', `${'x'.repeat(15)}e\u0301`];
  const rejected = [
    '', ' ', '\u3000', ' \u0301 ', '\u3164',
    'a\u200Bb', 'a\u200Eb', 'a\u2060b', '\uFEFF&', 'a\u00ADb', 'a\u200Db',
    '\t&', '&\n', 'a\u0000b', 'a\u007Fb', 'a\u0085b', 'a\u2028b', 'a\u2029b',
    'a\uD800b', '\uDC00&',
    '\u0301 & ', '\u0308 & ', '\uFE0F&', '\u{1F3FD}&', '\u{1F1EF}', '\u{1F1EF}\u{1F1F5}', '&\u{1F1EF}',
    '\u1161&', '\u11A8&', '&\u1100',
    '\uE000', '&\uE000', '\u0378', '\uFFFF', '\uFDD0&',
    '\u2800', '&\u2800', '&\u3164', '\u3164&\u3164', '&\u034F', '\uFFA0&', 'a\u115Fb', '&\u17B4',
    'x'.repeat(17), '\u{1F3BB}'.repeat(9)
  ];
  for (const phrase of accepted) expect(validJoinPhrase(phrase), JSON.stringify(phrase)).toBe(true);
  for (const phrase of rejected) expect(validJoinPhrase(phrase), JSON.stringify(phrase)).toBe(false);
});

test('a label refuses control and invisible formatting characters and more than 200 characters after NFC', () => {
  expect(labelIssue(null)).toBeNull(); expect(labelIssue(labelEntry('Lorem Records'))).toBeNull();
  expect(labelIssue(labelEntry('Lorem\u200B'))).toBe('invalid'); expect(labelIssue(labelEntry('Lorem\u0007'))).toBe('invalid');
  expect(labelIssue({ name: '\uFEFFLorem', musicBrainzId: null })).toBeNull(); expect(labelIssue(labelEntry('Lo\uFEFFrem'))).toBe('invalid');
  expect(labelIssue(labelEntry('\u0958'.repeat(101)))).toBe('too_long');
});
